// Independent DR-0154 wire-vector reconstruction for the AvailabilityIdentity
// (0xD030), AvailabilityVote (0xD031), AvailabilityCertificate (0xD032),
// ArtifactEntry (0xD033), ArtifactManifest (0xD034) and PublicationBundle
// (0xD035) canonical frames. No Rust encoder is invoked; this reimplements the
// shared canonical-frame layout (crates/canonical-encoding) and the
// self-describing Digest32 frame (0x0103) from scratch, from the source
// field values in crates/consensus/src/availability.rs and
// crates/consensus/src/availability/bundle.rs, and checks the
// result against the exact hex/byte vectors pinned by the co-located Rust
// tests `availability_identity_encoding_vector_0xd030_is_stable`,
// `availability_vote_encoding_vector_0xd031_is_stable`,
// `availability_certificate_encoding_vector_0xd032_is_stable`,
// `artifact_entry_encoding_vector_0xd033_is_stable`,
// `artifact_manifest_encoding_vector_0xd034_is_stable` and
// `publication_bundle_encoding_vector_0xd035_is_stable`.
// Run: node scripts/availability-vectors.mjs
import assert from 'node:assert/strict';

const u16 = (n) => { const b = Buffer.alloc(2); b.writeUInt16LE(n); return b; };
const u32 = (n) => { const b = Buffer.alloc(4); b.writeUInt32LE(n); return b; };
const u64 = (n) => { const b = Buffer.alloc(8); b.writeBigUInt64LE(BigInt(n)); return b; };
const frame = (id, version, fields) => Buffer.concat([
  Buffer.from('SNRE'), u16(id), u16(version), u16(fields.length),
  ...fields.flatMap(([key, value]) => [u16(key), u32(value.length), value]),
]);

const ENCODING_VERSION = 1;
const AVAILABILITY_IDENTITY_TYPE_ID = 0xd030;
const AVAILABILITY_VOTE_TYPE_ID = 0xd031;
const AVAILABILITY_CERTIFICATE_TYPE_ID = 0xd032;
const DIGEST32_TYPE_ID = 0x0103;
const SHA2_256_ALGORITHM_ID = 1;
const ED25519_SCHEME_ID = 1;

const digest32 = (byte) => frame(DIGEST32_TYPE_ID, 1, [
  [1, u16(SHA2_256_ALGORITHM_ID)],
  [2, Buffer.alloc(32, byte)],
]);

// `vector_identity()` in crates/consensus/src/availability.rs.
const CHAIN_ID = 'dr0154-vectors';
const PROTOCOL_VERSION = 3;
const EPOCH = 9;
const DOMAIN = Buffer.alloc(32, 0x44);
const REQUEST_ID = Buffer.alloc(32, 0x55);
const SIGNED_INTENT_DIGEST = digest32(0xaa);
const EXECUTION_COMMITMENT = digest32(0xbb);
const SEMANTIC_ARTIFACTS_DIGEST = digest32(0xcc);

const availabilityIdentity = () => frame(AVAILABILITY_IDENTITY_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(CHAIN_ID)],
  [2, u32(PROTOCOL_VERSION)],
  [3, u64(EPOCH)],
  [4, DOMAIN],
  [5, REQUEST_ID],
  [6, SIGNED_INTENT_DIGEST],
  [7, EXECUTION_COMMITMENT],
  [8, SEMANTIC_ARTIFACTS_DIGEST],
]);

// `vector_vote()`: validator all-0x01, Ed25519 scheme, signature all-0x5A.
const availabilityVote = (validatorByte, signatureByte) => frame(AVAILABILITY_VOTE_TYPE_ID, ENCODING_VERSION, [
  [1, availabilityIdentity()],
  [2, Buffer.alloc(32, validatorByte)],
  [3, u16(ED25519_SCHEME_ID)],
  [4, Buffer.alloc(64, signatureByte)],
]);

const voteA = availabilityVote(0x01, 0x5a);
const voteB = availabilityVote(0x02, 0x7c);

// `availability_certificate_encoding_vector_0xd032_is_stable`: identity plus
// vote_a and vote_b in validator order.
const availabilityCertificate = frame(AVAILABILITY_CERTIFICATE_TYPE_ID, ENCODING_VERSION, [
  [1, availabilityIdentity()],
  [2, u32(2)],
  [3, voteA],
  [4, voteB],
]);

// --- DR-0154 publication bundle family -------------------------------------
// Source field values: `vector_entry`/`vector_manifest`/`vector_bundle` in
// crates/consensus/src/availability/bundle/tests.rs.
const ARTIFACT_ENTRY_TYPE_ID = 0xd033;
const ARTIFACT_MANIFEST_TYPE_ID = 0xd034;
const PUBLICATION_BUNDLE_TYPE_ID = 0xd035;
const FAST_VOTE_PAYLOAD_TYPE_ID = 0xd006;
const FAST_VOTE_TYPE_ID = 0xd007;
const FAST_CERTIFICATE_TYPE_ID = 0xd008;
const ARTIFACT_KIND_STATE_VALUE = 1;
const ARTIFACT_KIND_OBJECT_BODY = 2;
const LOGICAL_COMMITMENT_PROFILE = 2;

const artifactEntry = (kind, identity, digestByte, length) => frame(ARTIFACT_ENTRY_TYPE_ID, ENCODING_VERSION, [
  [1, u16(kind)],
  [2, Buffer.from(identity)],
  [3, digest32(digestByte)],
  [4, u32(length)],
]);

const entryStateValue = artifactEntry(ARTIFACT_KIND_STATE_VALUE, 'key', 0xaa, 3);
const entryObjectBody = artifactEntry(ARTIFACT_KIND_OBJECT_BODY, 'obj', 0xbb, 4);

// Entries are canonically ordered by (kind, identity); StateValue (1) sorts
// before ObjectBody (2).
const artifactManifest = frame(ARTIFACT_MANIFEST_TYPE_ID, ENCODING_VERSION, [
  [1, u32(2)],
  [2, entryStateValue],
  [3, entryObjectBody],
]);

// `vector_bundle()` carries one literal FastVote/FastCertificate so the bundle
// vector depends only on framing, never on a signing key or hash suite.
const BUNDLE_CHAIN_ID = 'dr0154-vectors';
const fastVotePayload = frame(FAST_VOTE_PAYLOAD_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(BUNDLE_CHAIN_ID)],
  [2, u32(PROTOCOL_VERSION)],
  [3, u64(EPOCH)],
  [4, digest32(0x11)],
  [5, digest32(0x22)],
  [6, Buffer.alloc(32, 0x01)],
  [7, u16(ED25519_SCHEME_ID)],
  [8, digest32(0x33)],
]);
const fastVote = frame(FAST_VOTE_TYPE_ID, ENCODING_VERSION, [
  [1, fastVotePayload],
  [2, Buffer.alloc(64, 0x5a)],
]);
const fastCertificate = frame(FAST_CERTIFICATE_TYPE_ID, ENCODING_VERSION, [
  [1, Buffer.from(BUNDLE_CHAIN_ID)],
  [2, u32(PROTOCOL_VERSION)],
  [3, u64(EPOCH)],
  [4, digest32(0x11)],
  [5, digest32(0x22)],
  [6, digest32(0x33)],
  [7, u32(1)],
  [8, fastVote],
]);

const publicationBundle = frame(PUBLICATION_BUNDLE_TYPE_ID, ENCODING_VERSION, [
  [1, DOMAIN],
  [2, REQUEST_ID],
  [3, u16(LOGICAL_COMMITMENT_PROFILE)],
  [4, Buffer.from('intent')],
  [5, fastCertificate],
  [6, Buffer.from('witness')],
  [7, artifactManifest],
  [8, u32(2)],
  [9, Buffer.from('key')],
  [10, Buffer.from('obj!')],
]);

const vectors = {
  availabilityIdentity0xd030: availabilityIdentity(),
  availabilityVote0xd031: voteA,
  availabilityCertificate0xd032: availabilityCertificate,
  artifactEntry0xd033: entryStateValue,
  artifactManifest0xd034: artifactManifest,
  publicationBundle0xd035: publicationBundle,
};

const expected = {
  availabilityIdentity0xd030: '',
  availabilityVote0xd031: '',
  availabilityCertificate0xd032: '',
};

expected.artifactEntry0xd033 = '534e524533d00100040001000200000001000200030000006b6579030038000000534e52450301010002000100020000000100020020000000aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa04000400000003000000';
expected.artifactManifest0xd034 = '';
expected.publicationBundle0xd035 = '';

for (const [name, bytes] of Object.entries(vectors)) {
  const hex = bytes.toString('hex');
  assert.equal(hex, expected[name], `${name} hex mismatch`);
  console.log(JSON.stringify({ name, length: bytes.length, hex }));
}
